const BUILTIN_MEDIA=[{"key":"hangzhou-monopoly:cover","name":"hangzhou-board.webp","type":"image/webp","data":"data:image/webp;base64,"},{"key":"hangzhou-monopoly:ui","name":"hangzhou-property-ui.webp","type":"image/webp","data":"data:image/webp;base64,"},{"key":"hangzhou-monopoly:voice","name":"hangzhou-narration.webp","type":"image/webp","data":"data:image/webp;base64,"},{"key":"hangzhou-monopoly:portrait","name":"hangzhou-portrait-layer.webp","type":"image/webp","data":"data:image/webp;base64,"}];
const TOOL_KINDS=['Blender','ComfyUI','Unity','其他'];
const DEFAULT_TOOLS=[{id:'tool-blender',kind:'Blender',title:'Blender 工具',summary:'插件、批处理与资产辅助工具。',github:''},{id:'tool-comfyui',kind:'ComfyUI',title:'ComfyUI 工作流',summary:'节点工作流与图像制作流程。',github:''},{id:'tool-unity',kind:'Unity',title:'Unity 工具',summary:'编辑器扩展与项目制作工具。',github:''},{id:'tool-other',kind:'其他',title:'其他制作工具',summary:'更多脚本与制作流程。',github:''}];
function safeGitHub(value,repo=true){try{const u=new URL(String(value||'').trim());return u.protocol==='https:'&&u.hostname==='github.com'&&!u.port&&!u.username&&!u.password&&u.pathname.split('/').filter(Boolean).length>=(repo?2:1)?u.href:''}catch{return ''}}
function normalizeTools(raw){const values=Array.isArray(raw)?raw:DEFAULT_TOOLS,seen=new Set();return values.slice(0,60).filter(t=>{if(!t||!/^tool-[a-z0-9-]{1,60}$/.test(t.id)||seen.has(t.id))return false;seen.add(t.id);return true}).map(t=>({id:t.id,kind:TOOL_KINDS.includes(t.kind)?t.kind:'其他',title:String(t.title||'未命名工具').slice(0,80),summary:String(t.summary||'').slice(0,1200),github:safeGitHub(t.github)}))}
function contentKeys(value){return new Set([...BASE_PROJECTS.flatMap(p=>[p.id+':cover',...p.slots.map(s=>p.id+':'+s[0])]),...(value.tools||[]).flatMap(t=>[t.id+':cover',t.id+':demo'])])}
function syncContentKeys(){validKeys.clear();for(const key of contentKeys(state))validKeys.add(key)}
function toolArtwork(kind){const geometry=kind==='ComfyUI'?'<rect x="45" y="38" width="72" height="52" rx="4"/><rect x="180" y="68" width="72" height="52" rx="4"/><rect x="314" y="38" width="72" height="52" rx="4"/><path d="M117 64C152 64 145 94 180 94M252 94C282 94 282 64 314 64"/><circle cx="117" cy="64" r="3"/><circle cx="180" cy="94" r="3"/><circle cx="252" cy="94" r="3"/><circle cx="314" cy="64" r="3"/>':kind==='Blender'?'<path d="m216 20 64 35v67l-64 35-64-35V55Zm-64 35 64 36 64-36M216 91v66M184 38l64 36v67M248 38l-64 36v67M152 89l64 35 64-35"/>':kind==='Unity'?'<path d="M105 88h80m62 0h80M156 88v-45h58m-58 45v45h58"/><rect x="185" y="65" width="62" height="46" rx="3"/><circle cx="105" cy="88" r="6"/><circle cx="327" cy="88" r="6"/><circle cx="218" cy="43" r="4"/><circle cx="218" cy="133" r="4"/>':'<path d="m160 60-28 28 28 28m112-56 28 28-28 28m-45-70-24 140"/>';return `<svg viewBox="0 0 432 176" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.3">${geometry}</g></svg>`}
function renderTechnical(){const tools=state.tools||[];$('#technical-count').textContent=String(tools.length).padStart(2,'0');$('#tool-grid').innerHTML=tools.map(t=>{const repo=safeGitHub(t.github),preview=assets.has(t.id+':demo')?t.id+':demo':assets.has(t.id+':cover')?t.id+':cover':null;return `<article class="tool-card"><div class="tool-card-top"><span>${escapeHTML(t.kind)}</span><small>${preview||repo?'已添加内容':'预留位置'}</small></div><div class="tool-visual">${preview?visualHTML(t,preview,true):toolArtwork(t.kind)}</div><div class="tool-info"><h3>${escapeHTML(t.title)}</h3><p>${escapeHTML(t.summary)}</p>${repo?`<a class="tool-repository" href="${escapeHTML(repo)}" target="_blank" rel="noopener noreferrer">GitHub 仓库 <span aria-hidden="true">↗</span></a>`:'<span class="tool-repository pending">GitHub 仓库待补充</span>'}</div></article>`}).join('');$('#tools-empty').hidden=!!tools.length;const github=safeGitHub(state.githubProfile,false),link=$('#technical-github');link.hidden=!github;if(github)link.href=github}
function selectPortfolio(module,updateHash=false){const tech=module==='technology';$$('[data-module]').forEach(b=>{const on=(b.dataset.module==='technology')===tech;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});$('#art-panel').hidden=tech;$('#technology-panel').hidden=!tech;$('#module-description').textContent=tech?'制作工具、编辑器扩展与可复用工作流。':'角色、场景、卡牌与实时视觉表现。';document.querySelectorAll('.works video').forEach(v=>v.pause());if(updateHash)history.replaceState(null,'',tech?'#technology':'#works')}
function collectToolDrafts(){return [...document.querySelectorAll('[data-tool-editor]')].map(el=>({id:el.dataset.toolEditor,kind:el.querySelector('[data-tool-kind]').value,title:el.querySelector('[data-tool-title]').value.trim()||'未命名工具',summary:el.querySelector('[data-tool-summary]').value.trim(),github:el.querySelector('[data-tool-github]').value.trim()}))}
function renderToolManager(drafts=state.tools){$('#edit-github-profile').value=state.githubProfile||'';$('#manager-tools').innerHTML=drafts.map(t=>`<details class="manager-project tool-editor" data-tool-editor="${t.id}"><summary>${escapeHTML(t.title)}<small>技术 / ${escapeHTML(t.kind)}</small></summary><div class="manager-fields"><div class="form-row"><label>工具名称<input data-tool-title maxlength="80" value="${escapeHTML(t.title)}"></label><label>工具分类<select data-tool-kind>${TOOL_KINDS.map(k=>`<option ${k===t.kind?'selected':''}>${k}</option>`).join('')}</select></label></div><label>简短介绍<textarea data-tool-summary maxlength="1200">${escapeHTML(t.summary)}</textarea></label><label>GitHub 仓库链接<input type="url" data-tool-github value="${escapeHTML(t.github)}" placeholder="https://github.com/用户名/仓库名"></label><div class="upload-grid">${uploadField(t,'cover','工具封面 / 工作流截图')}${uploadField(t,'demo','工具演示 / 视频或图像')}</div><button type="button" class="tool-remove" data-remove-tool="${t.id}">移除此工具</button></div></details>`).join('');$('#manager-tools').querySelectorAll('[data-upload]').forEach(input=>input.onchange=()=>uploadAsset(input));$('#manager-tools').querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>removeAsset(button.dataset.remove));$('#manager-tools').querySelectorAll('[data-remove-tool]').forEach(button=>button.onclick=async()=>{const drafts=collectToolDrafts().filter(t=>t.id!==button.dataset.removeTool);try{const next={...state,tools:normalizeTools(drafts)};await dbWrite('state',next);state=next;syncContentKeys();renderToolManager();renderTechnical();setStatus('工具已移除。原有备份可用于恢复。')}catch(error){setStatus(errorMessage(error))}})}
function initializePortfolioModules(){$$('[data-module]').forEach(b=>{b.onclick=()=>selectPortfolio(b.dataset.module,true);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const module=e.key==='Home'?'art':e.key==='End'?'technology':b.dataset.module==='art'?'technology':'art';selectPortfolio(module,true);document.querySelector(`[data-module="${module}"]`).focus()}}});$$('[data-nav-module]').forEach(a=>a.onclick=()=>selectPortfolio(a.dataset.navModule));window.addEventListener('hashchange',()=>{if(location.hash==='#technology'||location.hash==='#works')selectPortfolio(location.hash==='#technology'?'technology':'art')});$('#add-tool').onclick=async()=>{const drafts=collectToolDrafts();if(drafts.length>=60){setStatus('工具数量上限为 60。');return}const tool={id:'tool-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),kind:'其他',title:'新的制作工具',summary:'',github:''};try{const next={...state,tools:normalizeTools([...drafts,tool])};await dbWrite('state',next);state=next;syncContentKeys();renderToolManager();renderTechnical();const editor=document.querySelector(`[data-tool-editor="${tool.id}"]`);editor.open=true;editor.querySelector('[data-tool-title]').focus();setStatus('已新增工具，可以补充素材和 GitHub 链接。')}catch(error){setStatus(errorMessage(error))}};selectPortfolio(location.hash==='#technology'?'technology':'art')}

function legacyGalleryHTML(p){const filled=p.slots.filter(([key])=>assets.has(p.id+':'+key));if(!filled.length)return '';return `<h3 class="detail-gallery-heading">作品画面</h3><div class="detail-gallery legacy-gallery">${filled.map(([key,label])=>{const id=p.id+':'+key,item=assets.get(id),image=item.type.startsWith('image/');return `<figure class="gallery-slot ${image?'gallery-image':'gallery-video'}">${image?`<button type="button" class="slot-visual" data-zoom-asset="${id}" data-caption="${escapeHTML(label)}" aria-label="放大查看${escapeHTML(label)}">${visualHTML(p,id)}<span class="gallery-enlarge" aria-hidden="true">↗</span></button>`:`<div class="slot-visual">${visualHTML(p,id,true)}</div>`}<figcaption>${escapeHTML(label)}</figcaption></figure>`}).join('')}</div>`}
async function seedLegacyMedia(){try{if(!db)return;const seeded=await dbRead('builtin-seeded-legacy-v1');if(!seeded&&!EMBEDDED_CONTENT?.legacySeeded){for(const item of LEGACY_MEDIA)if(validKeys.has(item.key)&&!assets.has(item.key)){const value={blob:fromDataURL(item.data,item.type),name:item.name,type:item.type};await dbWrite('asset:'+item.key,value);assets.set(item.key,value)}}await dbWrite('builtin-seeded-legacy-v1',true)}catch(error){toast('旧站素材保存失败：'+errorMessage(error))}}
function mountLegacyProfile(){const photo=$('#profile-photo');if(photo)photo.src=LEGACY_PROFILE.portrait;const resume=$('#download-resume');if(resume){resume.href=URL.createObjectURL(fromDataURL(LEGACY_PROFILE.resume,'application/pdf'));resume.download='王立焱-简历.pdf'}document.addEventListener('click',e=>{const button=e.target.closest('[data-zoom-asset]');if(!button)return;const key=button.dataset.zoomAsset;if(!assets.has(key))return;const dialog=$('#image-dialog');$('#image-caption').textContent=button.dataset.caption;const img=$('#expanded-image');img.src=assetURL(key);img.alt=button.dataset.caption;dialog.showModal();dialog.querySelector('.image-scroll').scrollTop=0})}

const DEFAULT_STATE={version:1,tools:structuredClone(DEFAULT_TOOLS),githubProfile:'',email:'',hero:'',projects:BASE_PROJECTS.map(p=>({id:p.id,title:p.title,summary:p.summary}))};
const $=s=>document.querySelector(s);
const $$=s=>Array.from(document.querySelectorAll(s));
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ORIGINAL_HTML='<!doctype html>\n'+document.documentElement.outerHTML;
const originalCSS=document.querySelector('link[href="style.css"]')?fetch('style.css').then(r=>{if(!r.ok)throw new Error('样式文件读取失败');return r.text()}):Promise.resolve($('#application-style')?.textContent||'');
const originalJS=document.querySelector('script[src="app.js"]')?fetch('app.js').then(r=>{if(!r.ok)throw new Error('脚本文件读取失败');return r.text()}):Promise.resolve($('#application-code')?.textContent||'');
// Surface export problems in the export action, without unhandled rejections on file://.
originalCSS.catch(()=>{});originalJS.catch(()=>{});
let state=structuredClone(DEFAULT_STATE),assets=new Map(),urls=new Map(),db=null,filter='all',activeProject=null;
const validKeys=new Set(BASE_PROJECTS.flatMap(p=>[p.id+':cover',...p.slots.map(s=>p.id+':'+s[0])]));
const MIME_TYPES=new Set(['image/png','image/jpeg','image/webp','image/gif','video/mp4','video/webm']);
const MAX_FILE=150*1024*1024;
let EMBEDDED_CONTENT=null;try{EMBEDDED_CONTENT=JSON.parse($('#site-data').textContent)}catch{}
const dbName='wang-liyan-lab-v1-'+(EMBEDDED_CONTENT?.snapshotId||'draft');
const dbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('浏览器不支持本地素材保存'));return}const req=indexedDB.open(dbName,1);req.onupgradeneeded=()=>req.result.createObjectStore('content');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
dbPromise.catch(()=>{});
function dbRead(key){return new Promise((resolve,reject)=>{const r=db.transaction('content').objectStore('content').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbWrite(key,value){return new Promise((resolve,reject)=>{if(!db){reject(new Error('本地存储不可用，请保持页面打开并导出备份'));return}const tx=db.transaction('content','readwrite');tx.objectStore('content').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('保存中断'))})}
function dbRemove(key){return new Promise((resolve,reject)=>{if(!db){reject(new Error('本地存储不可用'));return}const tx=db.transaction('content','readwrite');tx.objectStore('content').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function normalizeState(raw){if(!raw||raw.version!==1||!Array.isArray(raw.projects))throw new Error('备份格式或版本不正确');return {version:1,tools:normalizeTools(raw.tools),githubProfile:safeGitHub(raw.githubProfile,false),email:typeof raw.email==='string'?raw.email.slice(0,254):'',hero:BASE_PROJECTS.some(p=>p.id===raw.hero)?raw.hero:'',projects:BASE_PROJECTS.map(p=>{const saved=raw.projects.find(x=>x&&x.id===p.id)||{};return{id:p.id,title:typeof saved.title==='string'?saved.title.slice(0,80):p.title,summary:typeof saved.summary==='string'?saved.summary.slice(0,1200):p.summary}})}}
function projectData(){return BASE_PROJECTS.map(p=>({...p,...state.projects.find(x=>x.id===p.id)}))}
function assetURL(key){if(!assets.has(key))return null;if(!urls.has(key))urls.set(key,URL.createObjectURL(assets.get(key).blob));return urls.get(key)}
function releaseURL(key){if(urls.has(key)){URL.revokeObjectURL(urls.get(key));urls.delete(key)}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function setStatus(message){$('#manager-status').textContent=message}
function errorMessage(error){if(error?.name==='QuotaExceededError')return '浏览器存储空间不足。请先备份，压缩视频或删除不需要的素材。';return error?.message||'操作失败，请重试'}
function safeEmail(value){return /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(value)?value:''}
function makeArt(kind){
  const prefix='art-'+kind;let shapes='';
  const glow=`<defs><radialGradient id="${prefix}-g"><stop stop-color="#8bdcf0"/><stop offset=".2" stop-color="#4c7f9d"/><stop offset=".55" stop-color="#213b59"/><stop offset="1" stop-color="#101b2a"/></radialGradient><linearGradient id="${prefix}-l" x2="1" y2="1"><stop stop-color="#9be7ef"/><stop offset=".6" stop-color="#4d758b"/><stop offset="1" stop-color="#142333"/></linearGradient></defs>`;
  if(kind==='solar'){shapes='<circle cx="482" cy="283" r="156" fill="url(#'+prefix+'-g)"/><circle cx="482" cy="283" r="155" stroke="#77b6d0" stroke-opacity=".35"/>';for(let i=0;i<7;i++)shapes+=`<ellipse cx="450" cy="300" rx="${170+i*32}" ry="${44+i*13}" transform="rotate(-24 450 300)" stroke="#89dce9" stroke-opacity="${.44-i*.04}"/>`;shapes+='<circle cx="185" cy="365" r="17" fill="#7189b3"/><circle cx="688" cy="189" r="9" fill="#9edee7"/>'}
  else if(kind==='water'){for(let j=0;j<24;j++){let path='';for(let i=0;i<=60;i++){const x=80+i*12,y=185+j*10+Math.sin(i*.16+j*.15)*30+Math.sin(i*.08-j*.2)*22;path+=(i?'L':'M')+x+' '+y.toFixed(1)}shapes+=`<path d="${path}" stroke="${j%3?'#5aacc0':'#a1dce4'}" stroke-opacity="${.25+j*.025}"/>`}shapes+='<path d="M110 450H790M450 80v400" stroke="#5d9fa6" stroke-opacity=".12"/>'}
  else if(kind==='nba'){shapes='<path d="M200 420 450 190 700 420 450 530Z" fill="#182838" stroke="#466782"/><path d="M275 420 450 260 625 420 450 485Z" stroke="#548097"/><ellipse cx="450" cy="355" rx="120" ry="40" stroke="#70d8e5" stroke-width="3"/><path d="M330 355 355 465M570 355 545 465M370 382 390 476M530 382 510 476M410 394 425 480M490 394 475 480" stroke="#5f8ea2"/><circle cx="450" cy="217" r="55" fill="url(#'+prefix+'-l)"/><path d="M400 217h100M450 162v110M410 180q80 34 80 72M490 180q-80 34-80 72" stroke="#203b4e"/>'}
  else if(kind==='alien'){shapes='<circle cx="450" cy="285" r="175" stroke="#5c849d" stroke-opacity=".4"/><ellipse cx="450" cy="285" rx="175" ry="65" stroke="#5c849d" stroke-opacity=".4"/><path d="M450 100v360M275 285h350M330 150l240 270M570 150 330 420" stroke="#405e76" stroke-opacity=".5"/><path d="M330 435h240L540 270 450 180 360 270Z" fill="#122235" stroke="#85ceda"/><path d="M450 180v255M360 270l180 0M330 435 450 340 570 435" stroke="#568ba3"/><circle cx="450" cy="285" r="48" fill="url(#'+prefix+'-g)"/>'}
  else if(kind==='hero'){shapes='<path d="M210 420 340 180 450 350 560 150 710 420 450 490Z" fill="#233a43" stroke="#5e8b93"/><path d="M340 180 360 415 450 350 560 150 540 410 710 420M210 420 360 415 450 490 540 410" stroke="#71a6b0"/><path d="M450 210 420 270 450 385 480 270Z" fill="#83c8d3" stroke="#b5e4e8"/><path d="M405 278h90M450 385v45" stroke="#80c9d0" stroke-width="4"/>'}
  else if(kind==='cards'){for(let j=-1;j<=1;j++)shapes+=`<g transform="translate(${450+j*164} 290) rotate(${j*14})"><rect x="-90" y="-138" width="180" height="276" rx="8" fill="#142235" stroke="${j?'#54788d':'#8ed6e2'}"/><rect x="-76" y="-124" width="152" height="165" rx="3" stroke="#3d5c79"/><path d="M0-95 45-32 0 26-45-32Z" fill="url(#${prefix}-l)"/><path d="M-61 70H61M-61 85h100M-61 100h85" stroke="#53788a"/></g>`}
  else{shapes='<ellipse cx="450" cy="455" rx="140" ry="32" stroke="#7acfd7"/><path d="M310 455V145L450 95 590 145V455M310 145 450 195 590 145M450 195v292" stroke="#416c8a"/><path d="M425 262 398 325 420 350 415 413h24l11-58 11 58h24l-5-63 22-25-27-63Z" fill="#243f55" stroke="#8bc9db"/><circle cx="450" cy="230" r="27" fill="url(#'+prefix+'-g)"/>';for(let i=0;i<20;i++)shapes+=`<path d="M390 ${190+i*12}h120" stroke="#76cfdb" stroke-opacity=".12"/>`}
  let grid='';for(let x=0;x<900;x+=60)grid+=`<path d="M${x} 0v560"/>`;for(let y=0;y<560;y+=60)grid+=`<path d="M0 ${y}h900"/>`;
  return `<svg viewBox="0 0 900 560" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${glow}<rect width="900" height="560" fill="#101b2a"/><g stroke="#55718f" stroke-opacity=".09" fill="none">${grid}</g><g fill="none">${shapes}</g><path d="M28 65V28h37M835 532h37v-37" fill="none" stroke="#4b6c83"/><text x="30" y="532" fill="#7394aa" font-size="10" font-family="monospace">VISUAL PLACEHOLDER / ${kind.toUpperCase()}</text></svg>`;
}
function visualHTML(p,key=p.id+':cover',controls=false){const asset=assets.get(key),url=assetURL(key);if(!asset)return `<div class="project-art">${makeArt(p.art)}</div>`;if(asset.type.startsWith('video/'))return `<video class="project-media" src="${url}" preload="metadata" muted playsinline ${controls?'controls':''} aria-label="${escapeHTML(p.title)}视频"></video>`;return `<img class="project-media" src="${url}" alt="${escapeHTML(p.title)}" loading="lazy">`}
function renderProjects(){$('.section-count').textContent=String(BASE_PROJECTS.length).padStart(2,'0');$('[data-filter="all"] span').textContent=BASE_PROJECTS.length;const projects=projectData().filter(p=>filter==='all'||p.filters.includes(filter));$('#project-grid').innerHTML=projects.map(p=>p.id==='dark-forest'?forestProjectHTML(p):`<article class="project-card" data-project="${p.id}"><button class="project-open" data-open="${p.id}" aria-label="查看${escapeHTML(p.title)}项目详情">${visualHTML(p)}${assets.has(p.id+':cover')?'':'<span class="placeholder-badge">视觉占位 / 待补原始素材</span>'}<span class="project-open-arrow" aria-hidden="true">↗</span></button><div class="project-info"><p class="project-category">${escapeHTML(p.category)}</p><h3><button data-open="${p.id}">${escapeHTML(p.title)}</button></h3><p class="project-summary">${escapeHTML(p.summary)}</p><div class="tags">${p.tags.map(t=>'<span>'+escapeHTML(t)+'</span>').join('')}</div></div></article>${p.id==='hangzhou-monopoly'?characterCompareHTML():''}`).join('');$$('[data-open]').forEach(b=>b.onclick=()=>openProject(b.dataset.open));renderContact();renderHero();renderTechnical();mountCharacterComparisons();mountForestShowcases()}
function renderContact(){const email=safeEmail(state.email);$('#contact-link').hidden=!email;$('#contact-pending').hidden=!!email;if(email)$('#contact-link').href='mailto:'+email}
function renderHero(){const v=$('#hero-viewport'),p=projectData().find(p=>p.id===state.hero);v.querySelector('.hero-upload')?.remove();const filled=p&&assets.has(p.id+':cover');v.classList.toggle('hero-has-media',!!filled);$('#lab-canvas').hidden=!!filled;v.querySelector('.viewport-caption').innerHTML=filled?`<span>${escapeHTML(p.title)}</span><small>项目原始素材</small>`:'<span>Wave field</span><small>程序化视觉占位 · 非项目实机</small>';v.querySelector('.viewport-meta').textContent=filled?'作品预览':'视觉交互原型';if(filled){const div=document.createElement('div');div.className='hero-upload';div.innerHTML=visualHTML(p,p.id+':cover',true);v.insertBefore(div,v.querySelector('.viewport-caption'));$('#pause-motion').hidden=true}else $('#pause-motion').hidden=false}
function openProject(id){const p=projectData().find(x=>x.id===id);if(!p)return;$('#project-dialog').classList.remove('forest-dialog');if(id==='dark-forest'){openForest();return}if(id==='hangzhou-monopoly'){openMonopoly(p);return}activeProject=id;$('#project-detail').innerHTML=`<div class="detail-hero">${visualHTML(p,p.id+':cover',true)}${assets.has(p.id+':cover')?'':'<span class="placeholder-badge">视觉占位 / 非项目实机画面</span>'}</div><div class="detail-content"><p class="project-category">${escapeHTML(p.category)}</p><h2>${escapeHTML(p.title)}</h2><p class="detail-summary">${escapeHTML(p.summary)}</p><div class="tags">${p.tags.map(t=>'<span>'+escapeHTML(t)+'</span>').join('')}</div><div class="detail-columns"><div><h3>${p.id==='hangzhou-monopoly'?'可核实的工程实现':'作品内容与职责'}</h3><ul>${p.role.map(t=>'<li>'+escapeHTML(t)+'</li>').join('')}</ul></div><div><h3>项目记录与待补细节</h3><ul>${p.notes.map(t=>'<li>'+escapeHTML(t)+'</li>').join('')}</ul></div></div>${p.breakdown?`<div class="technical-breakdown">${p.breakdown.map(b=>`<article><h3>${escapeHTML(b.title)}</h3><p>${escapeHTML(b.text)}</p><small>${escapeHTML(b.evidence)}</small></article>`).join('')}</div>`:''}${legacyGalleryHTML(p)}${p.video?`<p><a class="button" href="${p.video}" target="_blank" rel="noopener noreferrer">打开作品集内视频链接 ↗</a></p>`:''}<p class="source-note">${p.sourceNote?escapeHTML(p.sourceNote):`内容依据：所提供作品集 PDF，第 ${p.pages} 页（文件页序）。视频链接来自作品集，外部链接可用性待核实。`}</p></div>`;if(!$('#project-dialog').open)$('#project-dialog').showModal()}
function uploadField(p,key,label){const id=p.id+':'+key,asset=assets.get(id);return `<div class="upload-field"><label>${escapeHTML(label)}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm" data-upload="${id}"></label><span class="upload-state" data-upload-status="${id}">${asset?escapeHTML(asset.name):'尚未添加素材'}</span><button type="button" class="remove-asset" data-remove="${id}" ${asset?'':'hidden'}>移除此素材</button></div>`}
function renderManager(){const projects=projectData();$('#edit-email').value=state.email;$('#edit-hero').innerHTML='<option value="">交互式波面占位</option>'+projects.map(p=>`<option value="${p.id}">${escapeHTML(p.title)}封面</option>`).join('');$('#edit-hero').value=state.hero;$('#manager-projects').innerHTML=projects.map((p,i)=>`<details class="manager-project" ${i===0?'open':''}><summary>${escapeHTML(p.title)}<small>${p.sourceLabel?escapeHTML(p.sourceLabel):`PDF 第 ${p.pages} 页`} / 封面 + ${p.slots.length} 个内容位置</small></summary><div class="manager-fields"><label>项目标题<input data-title="${p.id}" maxlength="80" required value="${escapeHTML(p.title)}"></label><label>项目简介<textarea data-summary="${p.id}" maxlength="1200">${escapeHTML(p.summary)}</textarea></label><div class="upload-grid">${uploadField(p,'cover','项目封面 / 首页素材')}${p.slots.map(([key,label])=>uploadField(p,key,label)).join('')}</div></div></details>`).join('');$$('[data-upload]').forEach(input=>input.onchange=()=>uploadAsset(input));$$('[data-remove]').forEach(button=>button.onclick=()=>removeAsset(button.dataset.remove));renderToolManager();setStatus('支持 PNG / JPG / WebP / GIF / MP4 / WebM，每个文件不超过 150 MB。建议视频压缩至 50 MB 以下。素材选择后立即保存，文字修改请点击保存。')}
async function uploadAsset(input){const file=input.files[0],key=input.dataset.upload;if(!file)return;input.disabled=true;try{if(!MIME_TYPES.has(file.type))throw new Error('请使用 PNG、JPG、WebP、GIF、MP4 或 WebM 文件');if(file.size>MAX_FILE)throw new Error('文件超过 150 MB，请先压缩');const record={blob:file,name:file.name,type:file.type};await dbWrite('asset:'+key,record);releaseURL(key);assets.set(key,record);document.querySelector(`[data-upload-status="${key}"]`).textContent=file.name;document.querySelector(`[data-remove="${key}"]`).hidden=false;renderProjects();setStatus('已保存素材：'+file.name);toast('素材已保存到当前浏览器')}catch(error){setStatus(errorMessage(error))}finally{input.disabled=false;input.value=''}}
async function removeAsset(key){try{await dbRemove('asset:'+key);releaseURL(key);assets.delete(key);document.querySelector(`[data-upload-status="${key}"]`).textContent='尚未添加素材';document.querySelector(`[data-remove="${key}"]`).hidden=true;renderProjects();setStatus('素材已移除，可随时重新上传。')}catch(error){setStatus(errorMessage(error))}}
$('#manager-form').onsubmit=async e=>{e.preventDefault();const toolDrafts=collectToolDrafts(),profile=$('#edit-github-profile').value.trim();if(toolDrafts.some(t=>t.github&&!safeGitHub(t.github))||(profile&&!safeGitHub(profile,false))){setStatus('请填写有效的 https://github.com 仓库或主页链接。');return}const next={version:1,tools:normalizeTools(toolDrafts),githubProfile:safeGitHub(profile,false),email:$('#edit-email').value.trim(),hero:$('#edit-hero').value,projects:BASE_PROJECTS.map(p=>({id:p.id,title:document.querySelector(`[data-title="${p.id}"]`).value.trim()||p.title,summary:document.querySelector(`[data-summary="${p.id}"]`).value.trim()}))};try{await dbWrite('state',next);state=next;syncContentKeys();renderProjects();setStatus('文字与首页设置已保存。');toast('内容已保存')}catch(error){setStatus(errorMessage(error))}};
function blobToDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
function fromDataURL(value,type){if(typeof value!=='string'||!value.startsWith('data:'+type+';base64,'))throw new Error('备份内素材格式不正确');const bytes=atob(value.slice(value.indexOf(',')+1));if(bytes.length>MAX_FILE)throw new Error('备份内含超过 150 MB 的素材');return new Blob([Uint8Array.from(bytes,c=>c.charCodeAt(0))],{type})}
async function packageContent(){const media=[];for(const [key,item]of assets)if(validKeys.has(key))media.push({key,name:item.name,type:item.type,data:await blobToDataURL(item.blob)});return{version:1,builtinSeeded:true,legacySeeded:true,snapshotId:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),state,media}}
function download(blob,filename){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000)}
async function performExport(button,task){button.disabled=true;setStatus('正在准备文件，请稍候…');try{await task();setStatus('导出已触发，请查看浏览器下载。未保存的文字不会包含在导出文件中。')}catch(error){setStatus(errorMessage(error))}finally{button.disabled=false}}
$('#export-backup').onclick=()=>performExport($('#export-backup'),async()=>download(new Blob([JSON.stringify(await packageContent())],{type:'application/json'}),'王立焱-站点内容备份.json'));
$('#export-site').onclick=()=>performExport($('#export-site'),async()=>{const [css,js,content]=await Promise.all([originalCSS,originalJS,packageContent()]);if(!css||!js)throw new Error('页面源文件不可用，请通过本地预览地址打开后导出');const payload=JSON.stringify(content).replace(/</g,'\\u003c');let html=ORIGINAL_HTML.replace(/<script id="site-data" type="application\/json">[\s\S]*?<\/script>/,()=>'<script id="site-data" type="application/json">'+payload+'</script>');const style='<style id="application-style">'+css.replace(/<\/style/gi,'<\\/style')+'</style>';const code='<script id="application-code">'+js.replace(/<\/script/gi,'<\\/script')+'</script>';html=html.includes('<link rel="stylesheet" href="style.css">')?html.replace('<link rel="stylesheet" href="style.css">',()=>style):html.replace(/<style id="application-style">[\s\S]*?<\/style>/,()=>style);html=html.includes('<script src="app.js"></script>')?html.replace('<script src="app.js"></script>',()=>code):html.replace(/<script id="application-code">[\s\S]*?<\/script>/,()=>code);download(new Blob([html],{type:'text/html;charset=utf-8'}),'王立焱-个人站.html')});
$('#import-backup').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>400*1024*1024)throw new Error('备份过大，请使用较小的备份文件');const raw=JSON.parse(await file.text());if(raw.version!==1||!Array.isArray(raw.media))throw new Error('不是本站的内容备份');const next=normalizeState(raw.state),nextAssets=new Map();for(const item of raw.media){if(!contentKeys(next).has(item.key)||!MIME_TYPES.has(item.type)||nextAssets.has(item.key))throw new Error('备份包含无效或重复的素材位置');nextAssets.set(item.key,{blob:fromDataURL(item.data,item.type),name:String(item.name).slice(0,250),type:item.type})}if(!db)throw new Error('本地存储不可用');await new Promise((resolve,reject)=>{const tx=db.transaction('content','readwrite'),store=tx.objectStore('content');store.clear();store.put(next,'state');store.put(true,'builtin-seeded-monopoly');store.put(true,'builtin-seeded-legacy-v1');for(const [key,item]of nextAssets)store.put(item,'asset:'+key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('恢复失败'))});for(const key of urls.keys())releaseURL(key);state=next;syncContentKeys();assets=nextAssets;renderProjects();renderManager();setStatus('备份已恢复，替换了当前浏览器中本站的内容。')}catch(error){setStatus('恢复失败：'+errorMessage(error))}finally{e.target.value=''}};
$('#open-manager').onclick=()=>{renderManager();$('#manager-dialog').showModal()};
$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$$('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()});dialog.addEventListener('close',()=>{dialog.querySelectorAll('video').forEach(v=>v.pause());if(dialog.id==='project-dialog')activeProject=null})});
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProjects()});

// Lightweight canvas illustration. It demonstrates the site direction, not a Unity render.
const canvas=$('#lab-canvas'),ctx=canvas.getContext('2d');
let mode='surface',amplitude=.9,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,pointer={x:0,y:0},phase=0,lastTime=0;
function syncPause(){const b=$('#pause-motion');b.textContent=paused?'播放':'暂停';b.setAttribute('aria-label',paused?'播放视觉动画':'暂停视觉动画');b.setAttribute('aria-pressed',String(paused))}
syncPause();
$('#pause-motion').onclick=()=>{paused=!paused;syncPause();drawWave()};
$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$$('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});drawWave()});
$('#amplitude').oninput=e=>{amplitude=Number(e.target.value);drawWave()};
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width-.5;pointer.y=(e.clientY-r.top)/r.height-.5;if(paused)drawWave()});
canvas.addEventListener('pointerleave',()=>{pointer={x:0,y:0};if(paused)drawWave()});
function drawWave(){if(!ctx||canvas.hidden)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;const dpr=Math.min(devicePixelRatio||1,1.5);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#0d141e';ctx.fillRect(0,0,w,h);const glow=ctx.createRadialGradient(w*.55,h*.44,5,w*.55,h*.44,w*.6);glow.addColorStop(0,'#1b3545');glow.addColorStop(1,'#0d141e');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#23374b55';ctx.lineWidth=.5;for(let x=0;x<w;x+=35){ctx.beginPath();ctx.moveTo(x,44);ctx.lineTo(x,h-60);ctx.stroke()}for(let y=44;y<h-60;y+=35){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}const rows=36,cols=58,points=[];for(let j=0;j<=rows;j++){const row=[];for(let i=0;i<=cols;i++){const u=(i/cols-.5)*2.9,v=(j/rows-.5)*2.3,r=Math.sqrt(u*u+v*v);const height=(Math.sin(r*5.3-phase*1.4)*Math.exp(-r*.55)*.75+Math.sin(u*2.6+v*2.3+phase*.6)*.18)*amplitude;const x=w*.53+(u-v*.35)*w*.225+pointer.x*12;const y=h*.47+v*h*.15-height*h*.18+u*h*.045+pointer.y*8;row.push({x,y,z:height})}points.push(row)}if(mode==='surface'){for(let j=0;j<rows;j++){ctx.beginPath();points[j].forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));for(let i=cols;i>=0;i--)ctx.lineTo(points[j+1][i].x,points[j+1][i].y);ctx.closePath();const g=ctx.createLinearGradient(0,h*.2,w,h*.65);g.addColorStop(0,'#547f9c');g.addColorStop(.4,'#477d92');g.addColorStop(.65,'#34566f');g.addColorStop(1,'#8b8bad');ctx.fillStyle=g;ctx.globalAlpha=.8;ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=`rgba(137,223,235,${.15+j/rows*.3})`;ctx.lineWidth=.65;ctx.stroke()}}else{ctx.strokeStyle='#6dd8e9aa';ctx.lineWidth=.65;for(let j=0;j<=rows;j++){ctx.beginPath();points[j].forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke()}ctx.strokeStyle='#9698c973';for(let i=0;i<=cols;i+=2){ctx.beginPath();for(let j=0;j<=rows;j++){const p=points[j][i];j?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.stroke()}}ctx.fillStyle='#6d899d';ctx.font='9px monospace';ctx.fillText('Y',w*.85,h*.68);ctx.fillText('X',w*.88,h*.72);ctx.strokeStyle='#52748b';ctx.beginPath();ctx.moveTo(w*.84,h*.72);ctx.lineTo(w*.84,h*.66);ctx.moveTo(w*.84,h*.72);ctx.lineTo(w*.89,h*.72);ctx.stroke()}
function animate(time){requestAnimationFrame(animate);if(time-lastTime<42)return;const elapsed=Math.min((time-lastTime)/1000,.1);lastTime=time;if(paused||document.hidden||canvas.hidden||canvas.getBoundingClientRect().bottom<0)return;phase+=elapsed;drawWave()}
new ResizeObserver(drawWave).observe($('#hero-viewport'));requestAnimationFrame(animate);
// A lightweight web replay of the project's saved layers, bindings and animation curves.
const characterWidgets=new Set();let characterResources=null;
function characterCompareHTML(){return `<section class="character-comparison" aria-label="四个角色动态形象对比"><div class="character-heading"><div><p class="eyebrow">同一动作，四种性格</p><h3>角色动态对比</h3></div><div class="character-controls"><label>动作 <select class="character-action"><option value="Idle">待机</option><option value="Roll">投骰</option><option value="Purchase">购买</option><option value="Income">收益</option><option value="Victory">胜利</option></select></label><label class="character-speech-label"><input class="character-speech" type="checkbox" checked> 说话口型</label><button class="character-play" type="button">暂停</button><button class="character-replay" type="button">重播</button></div></div><div class="character-grid">${CHARACTER_DATA.map(c=>`<article class="character-card" style="--role-color:${c.color}"><div class="character-stage" data-role="${c.role}"><canvas aria-label="${c.name}动态形象"></canvas></div><h4>${c.name}</h4></article>`).join('')}</div><p class="character-note">根据工程分层素材与动作曲线制作的网页预览，支持眨眼与说话口型；可在素材管理中替换为四人的实机视频。</p><p class="character-load-status" role="status">正在加载角色…</p></section>`}
const cClamp=(x,a,b)=>Math.max(a,Math.min(b,x));
function cSmooth(a,b,x){const t=cClamp((x-a)/(b-a),0,1);return t*t*(3-2*t)}
function cMat(a,b){return[a[0]*b[0]+a[2]*b[1],a[1]*b[0]+a[3]*b[1],a[0]*b[2]+a[2]*b[3],a[1]*b[2]+a[3]*b[3],a[0]*b[4]+a[2]*b[5]+a[4],a[1]*b[4]+a[3]*b[5]+a[5]]}
function cPoint(m,x,y){return[m[0]*x+m[2]*y+m[4],m[1]*x+m[3]*y+m[5]]}
